mapper.update:
UPDATE CHATBOT_MESSAGE
   SET is_inappropriate = 1
 WHERE message_id = #{messageId}

mapper.select:
SELECT *
FROM (
    SELECT message_id, conversation_id, role, content, is_inappropriate, created_at
    FROM CHATBOT_MESSAGE
    WHERE conversation_id = #{conversationId}
    ORDER BY created_at DESC
    LIMIT #{limit}
) sub
ORDER BY created_at ASC
